import math

class Solution:
    def waysToReachStair(self, k: int) -> int:
        ans = 0
        for m in range(32):
            d = (1 << m) - k
            if 0 <= d <= m + 1:
                ans += math.comb(m + 1, d)
        return ans

class Solution {
public:
    long long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        if (k == 0 || k == n) return 1;
        if (k > n / 2) k = n - k;
        long long res = 1;
        for (int i = 1; i <= k; ++i) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }
    int waysToReachStair(int k) {
        int ans = 0;
        for (int m = 0; m < 32; ++m) {
            long long d = (1LL << m) - k;
            if (d >= 0 && d <= m + 1) {
                ans += comb(m + 1, d);
            }
        }
        return ans;
    }
};

class Solution {
    private long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        if (k == 0 || k == n) return 1;
        if (k > n / 2) k = n - k;
        long res = 1;
        for (int i = 1; i <= k; ++i) {
            res = res * (n - i + 1) / i;
        }
        return res;
    }
    public int waysToReachStair(int k) {
        int ans = 0;
        for (int m = 0; m < 32; ++m) {
            long d = (1L << m) - k;
            if (d >= 0 && d <= m + 1) {
                ans += comb(m + 1, (int) d);
            }
        }
        return ans;
    }
}

var waysToReachStair = function(k) {
    function comb(n, r) {
        if (r < 0 || r > n) return 0;
        if (r === 0 || r === n) return 1;
        if (r > Math.floor(n / 2)) r = n - r;
        let res = 1n;
        for (let i = 1n; i <= BigInt(r); ++i) {
            res = res * (BigInt(n) - i + 1n) / i;
        }
        return Number(res);
    }
    let ans = 0;
    for (let m = 0; m < 32; ++m) {
        const d = (1 << m) - k;
        if (d >= 0 && d <= m + 1) {
            ans += comb(m + 1, d);
        }
    }
    return ans;
};
